*{box-sizing:border-box}
:root{color-scheme:dark;--bg:#0b1020;--panel:#121a2e;--line:#26324d;--text:#eef2ff;--muted:#94a3b8;--good:#8fe3ab;--warn:#ffd17e;--bad:#ff9494;--accent:#7c9cff}
body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}
.wrap{max-width:1120px;margin:auto;padding:24px}
.head,.section-head{display:flex;align-items:center;justify-content:space-between;gap:16px}
h1{margin:0 0 3px;font-size:28px}h2{margin:2px 0;font-size:20px}h3{margin:0 0 10px;font-size:16px}
.muted{color:var(--muted)}.good{color:var(--good)}.warn-text{color:var(--warn)}.bad{color:var(--bad)}
.badge{display:inline-block;padding:4px 9px;border-radius:999px;background:#25304a;color:#dbeafe;font-size:12px;font-weight:800}
.section{margin-top:18px}.card{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:16px}
.eyebrow{font-size:10px;font-weight:800;letter-spacing:.12em;color:#8091b1}
.btn,.tab{border:1px solid var(--line);background:#121a2e;color:#cbd5e1;border-radius:10px;cursor:pointer;font-weight:700}
.btn{padding:8px 11px}.btn:disabled{opacity:.5;cursor:default}
.tabs{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0 14px}.tab{padding:9px 13px}.tab.active{background:#e2e8f0;color:#0f172a}
.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.grid4{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
.kpi-card{background:#0e1729;border:1px solid #26324d;border-radius:12px;padding:13px;min-width:0}.kpi-label{font-size:11px;color:#8fa0bd}.kpi{font-size:22px;font-weight:800;margin-top:4px;overflow-wrap:anywhere}
.top{display:grid;grid-template-columns:34px minmax(0,1fr) auto;gap:9px;align-items:center;padding:10px 0;border-bottom:1px solid #25304a}.top:last-child{border:0}.rank{font-size:17px;font-weight:800}.asset{font-weight:800}.right{text-align:right}
.kr-name{font-size:18px;font-weight:900;line-height:1.2}.kr-code{font-size:10px;color:#74839f;margin-top:3px;letter-spacing:.04em}.kr-action{margin-top:4px}.kr-top{padding:12px 0}
.pill{display:inline-block;padding:3px 7px;border-radius:999px;background:#25304a;font-size:11px;font-weight:800}.pill.ok{background:#153424;color:#a7efbd}.pill.warn{background:#3a2c16;color:#ffe3a7}.pill.badbg{background:#3a2028;color:#ffb1b1}
.account-summary{margin-top:14px}.holdings{margin-top:14px}.holding{display:grid;grid-template-columns:minmax(0,1.4fr) .7fr 1fr 1fr;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid #25304a}.holding:last-child{border:0}.holding .name{font-weight:750}.small{font-size:11px;color:#94a3b8}.statusline{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:10px}
.notice{padding:12px;border:1px dashed #3a4864;border-radius:11px;color:#a9b5cc;background:#0e1729}.error{border-color:#5e3339;color:#ffc1c1}.section-title{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}
